RETURNS trigger
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path = public
AS $fn$
BEGIN
  IF NEW.status IN ('pending', 'claimed', 'retryable') THEN
    NEW.status := 'cancelled';
    NEW.last_error := coalesce(NEW.last_error, 'Fila legada desativada; use o registro canônico da operação.');
  END IF;
  RETURN NEW;
END
$fn$;
