-- MASTER DETERMINISTIC UPDATE
-- MASTER 1.4.17: finalização atômica e determinística de UPDATE.
-- Control-plane only. Nunca incluir no pacote Client.

CREATE OR REPLACE FUNCTION public.finalize_installation_operation(
  _operation_id uuid,
  _owner text,
  _fencing_token bigint,
  _operation_status text,
  _summary text,
  _error_kind text,
  _detail jsonb,
  _steps jsonb,
  _installation_status text,
  _health text,
  _health_checks jsonb,
  _current_version text DEFAULT NULL,
  _touch_provisioned boolean DEFAULT false,
  _touch_validated boolean DEFAULT false
)
RETURNS boolean
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  _operation public.installation_operations%ROWTYPE;
  _target_release text;
  _target_commit text;
  _package_hash text;
  _package_total integer;
  _completed_migrations integer;
  _minimum_position integer;
  _maximum_position integer;
  _distinct_positions integer;
BEGIN
  IF _operation_status NOT IN ('success', 'failed', 'blocked', 'manual_review') THEN
    RAISE EXCEPTION 'Estado final inválido' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO _operation
  FROM public.installation_operations
  WHERE id = _operation_id
    AND status = 'running'
    AND lease_owner = _owner
    AND fencing_token = _fencing_token
    AND lease_expires_at > now()
  FOR UPDATE;
  IF NOT FOUND THEN RETURN false; END IF;

  IF _operation.kind = 'update' AND _operation_status = 'success' THEN
    _target_release := nullif(split_part(coalesce(_operation.baseline_id, ''), ':', 1), '');
    _target_commit := nullif(split_part(coalesce(_operation.baseline_id, ''), ':', 2), '');
    _package_hash := nullif(btrim(_operation.baseline_hash), '');
    _package_total := CASE WHEN split_part(coalesce(_operation.baseline_id, ''), ':', 3) ~ '^[1-9][0-9]*$'
      THEN split_part(_operation.baseline_id, ':', 3)::integer ELSE NULL END;

    IF _target_release IS NULL OR _target_commit IS NULL OR _package_hash !~ '^[0-9a-f]{64}$'
       OR _package_total IS NULL
       OR _current_version IS DISTINCT FROM _target_release
       OR _detail->'stageProgress'->>'updateRelease' IS DISTINCT FROM _target_release
       OR lower(coalesce(_detail->'stageProgress'->>'codeSourceSha', '')) <> lower(_target_commit)
       OR coalesce((_detail->'stageProgress'->>'codeDone')::boolean, false) IS NOT TRUE
       OR coalesce((_detail->'stageProgress'->>'updateDatabaseReconciled')::boolean, false) IS NOT TRUE
       OR coalesce((_detail->'stageProgress'->>'updateValidationPassed')::boolean, false) IS NOT TRUE
       OR jsonb_typeof(_steps) <> 'array'
       OR jsonb_array_length(_steps) = 0
       OR EXISTS (SELECT 1 FROM jsonb_array_elements(_steps) step WHERE step->>'state' <> 'done') THEN
      RAISE EXCEPTION 'Evidência canônica do UPDATE incompleta ou divergente' USING ERRCODE = '55000';
    END IF;

    SELECT count(*), min(package_position), max(package_position), count(DISTINCT package_position)
    INTO _completed_migrations, _minimum_position, _maximum_position, _distinct_positions
    FROM public.installation_operation_migrations
    WHERE operation_id = _operation_id
      AND status = 'completed'
      AND statement_index = total_statements;
    IF _completed_migrations <> _package_total
       OR _minimum_position <> 1
       OR _maximum_position <> _package_total
       OR _distinct_positions <> _package_total
       OR EXISTS (
         SELECT 1 FROM public.installation_operation_migrations
         WHERE operation_id = _operation_id
           AND (status <> 'completed'
             OR statement_index <> total_statements
             OR total_statements < 0
             OR migration_file !~ '^[0-9]{14}_[A-Za-z0-9_-]+\.sql$'
             OR fingerprint !~ '^[0-9a-f]{64}$')
       ) THEN
      RAISE EXCEPTION 'Ledger canônico do UPDATE incompleto ou inconsistente' USING ERRCODE = '55000';
    END IF;
    _detail := coalesce(_detail, '{}'::jsonb) || jsonb_build_object(
      'reconciliationState', 'reconciled',
      'appliedRelease', _target_release,
      'appliedCommitSha', _target_commit,
      'appliedPackageSha256', _package_hash,
      'reconciledAt', now()
    );
  END IF;

  UPDATE public.installation_operations
  SET status = _operation_status, summary = _summary, error_kind = _error_kind,
      detail = _detail, steps = _steps, current_step = NULL, next_attempt_at = NULL,
      next_command = NULL, lease_owner = NULL, lease_expires_at = NULL,
      run_token_hash = NULL, finished_at = now(), heartbeat_at = now(), last_report_at = now(),
      reconciled_at = CASE WHEN kind = 'update' AND _operation_status = 'success' THEN now() ELSE reconciled_at END
  WHERE id = _operation_id AND status = 'running' AND lease_owner = _owner
    AND fencing_token = _fencing_token;
  IF NOT FOUND THEN RETURN false; END IF;

  UPDATE public.installation_operation_attempts
  SET status = CASE WHEN _operation_status = 'success' THEN 'completed' ELSE _operation_status END,
      error_kind = _error_kind,
      error_message = CASE WHEN _operation_status = 'success' THEN NULL ELSE _summary END,
      retryable = false, finished_at = now(), heartbeat_at = now(), updated_at = now()
  WHERE operation_id = _operation_id AND fencing_token = _fencing_token AND status = 'running';

  UPDATE public.installations
  SET status = _installation_status, health = _health, health_checks = _health_checks,
      health_checked_at = now(), active_operation_id = NULL,
      last_error = CASE WHEN _operation_status = 'success' THEN NULL ELSE _summary END,
      current_version = coalesce(_current_version, current_version),
      pinned_release = CASE WHEN _operation.kind = 'update' AND _operation_status = 'success' THEN _target_release ELSE pinned_release END,
      pinned_commit_sha = CASE WHEN _operation.kind = 'update' AND _operation_status = 'success' THEN _target_commit ELSE pinned_commit_sha END,
      pinned_at = CASE WHEN _operation.kind = 'update' AND _operation_status = 'success' THEN now() ELSE pinned_at END,
      last_provisioned_at = CASE WHEN _touch_provisioned THEN now() ELSE last_provisioned_at END,
      last_validated_at = CASE WHEN _touch_validated THEN now() ELSE last_validated_at END,
      updated_at = now()
  WHERE id = _operation.installation_id AND active_operation_id = _operation_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Instalação não aponta para a operação finalizada' USING ERRCODE = '55000'; END IF;
  RETURN true;
END;
$$;
REVOKE ALL ON FUNCTION public.finalize_installation_operation(uuid,text,bigint,text,text,text,jsonb,jsonb,text,text,jsonb,text,boolean,boolean) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.finalize_installation_operation(uuid,text,bigint,text,text,text,jsonb,jsonb,text,text,jsonb,text,boolean,boolean) TO service_role;

CREATE OR REPLACE FUNCTION public.normalize_legacy_installation_operations(_max_idle_seconds integer DEFAULT 240)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE _leases integer := 0; _attempts integer := 0; _manual integer := 0; _inconsistent integer := 0;
BEGIN
  IF _max_idle_seconds < 30 OR _max_idle_seconds > 86400 THEN RAISE EXCEPTION 'Janela de normalização inválida' USING ERRCODE='22023'; END IF;
  WITH normalized AS (
    UPDATE public.installation_operations op SET status='manual_review',lease_owner=NULL,lease_expires_at=NULL,
      next_attempt_at=NULL,next_command=NULL,finished_at=coalesce(finished_at,now()),
      error_kind=coalesce(error_kind,'legacy_lease_inconsistent'),blocked_reason='legacy_lease_inconsistent',
      summary='Operação histórica bloqueada: lease inconsistente.',last_report_at=now()
    WHERE op.status IN ('pending','running','retryable') AND op.lease_owner IS NOT NULL AND op.lease_expires_at IS NULL RETURNING id
  ) SELECT count(*) INTO _leases FROM normalized;
  WITH closed AS (
    UPDATE public.installation_operation_attempts a SET status='orphaned',error_kind=coalesce(a.error_kind,'orphaned_attempt'),
      error_message=coalesce(a.error_message,'Tentativa sem lease ativo encerrada por reconciliação.'),retryable=false,
      finished_at=coalesce(a.finished_at,now()),heartbeat_at=now(),updated_at=now()
    FROM public.installation_operations op WHERE a.operation_id=op.id AND a.status='running'
      AND a.heartbeat_at<=now()-make_interval(secs=>_max_idle_seconds)
      AND (op.status NOT IN ('pending','running','retryable') OR op.fencing_token<>a.fencing_token OR op.lease_expires_at IS NULL OR op.lease_expires_at<=now()) RETURNING a.id
  ) SELECT count(*) INTO _attempts FROM closed;
  WITH detached AS (
    UPDATE public.installations i SET status='attention',health='degraded',active_operation_id=NULL,
      last_error=coalesce(op.summary,'Operação requer revisão manual.'),updated_at=now()
    FROM public.installation_operations op WHERE i.active_operation_id=op.id AND op.status IN ('blocked','manual_review','failed') RETURNING i.id
  ) SELECT count(*) INTO _manual FROM detached;
  WITH marked AS (
    UPDATE public.installations i SET status='attention',health='degraded',
      last_error='Estado updating sem operação executável; revisão manual obrigatória.',updated_at=now()
    WHERE i.status='updating' AND (i.active_operation_id IS NULL OR NOT EXISTS (
      SELECT 1 FROM public.installation_operations op WHERE op.id=i.active_operation_id
        AND op.installation_id=i.id AND op.status IN ('pending','running','retryable') AND op.detail->>'automated'='true')) RETURNING i.id
  ) SELECT count(*) INTO _inconsistent FROM marked;
  RETURN jsonb_build_object('normalizedLeases',_leases,'orphanedAttempts',_attempts,
    'detachedManualReview',_manual,'inconsistentUpdating',_inconsistent,'migrationsExecuted',0);
END $$;
REVOKE ALL ON FUNCTION public.normalize_legacy_installation_operations(integer) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.normalize_legacy_installation_operations(integer) TO service_role;

-- MASTER CONTROL-PLANE RELEASE
-- MASTER 1.4.24: estado e promoção atômica do próprio Control-plane.
-- Não reutiliza instalações ou operações de clientes.

CREATE TABLE IF NOT EXISTS public.control_plane_release_state (
  singleton boolean PRIMARY KEY DEFAULT true CHECK (singleton),
  current_version text,
  pinned_release text,
  pinned_commit_sha text,
  contract_sha256 text,
  generation bigint NOT NULL DEFAULT 0 CHECK (generation >= 0),
  promoted_by text,
  promoted_at timestamptz,
  updated_at timestamptz NOT NULL DEFAULT now(),
  CHECK (contract_sha256 IS NULL OR contract_sha256 ~ '^[0-9a-f]{64}$')
);
GRANT SELECT ON public.control_plane_release_state TO authenticated;
GRANT SELECT ON public.control_plane_release_state TO service_role;
ALTER TABLE public.control_plane_release_state ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS control_plane_release_state_super_admin_read ON public.control_plane_release_state;
CREATE POLICY control_plane_release_state_super_admin_read ON public.control_plane_release_state
  FOR SELECT TO authenticated USING (public.is_super_admin(auth.uid()));

CREATE TABLE IF NOT EXISTS public.control_plane_release_events (
  id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  generation bigint NOT NULL UNIQUE CHECK (generation > 0),
  previous_current_version text,
  previous_pinned_release text,
  previous_pinned_commit_sha text,
  target_version text NOT NULL,
  target_commit_sha text NOT NULL,
  contract_sha256 text NOT NULL CHECK (contract_sha256 ~ '^[0-9a-f]{64}$'),
  validation_evidence jsonb NOT NULL,
  promoted_by text NOT NULL CHECK (nullif(btrim(promoted_by), '') IS NOT NULL),
  promoted_at timestamptz NOT NULL DEFAULT now()
);
GRANT SELECT ON public.control_plane_release_events TO authenticated;
GRANT SELECT ON public.control_plane_release_events TO service_role;
ALTER TABLE public.control_plane_release_events ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS control_plane_release_events_super_admin_read ON public.control_plane_release_events;
CREATE POLICY control_plane_release_events_super_admin_read ON public.control_plane_release_events
  FOR SELECT TO authenticated USING (public.is_super_admin(auth.uid()));

CREATE OR REPLACE FUNCTION public.promote_control_plane_release(
  _expected_generation bigint,
  _expected_current_version text,
  _expected_pinned_release text,
  _expected_pinned_commit_sha text,
  _target_version text,
  _target_commit_sha text,
  _contract_sha256 text,
  _validation_evidence jsonb,
  _promoted_by text
) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE
  _state public.control_plane_release_state%ROWTYPE;
  _next_generation bigint;
BEGIN
  IF _expected_generation IS NULL OR nullif(btrim(_target_version),'') IS NULL
     OR nullif(btrim(_target_commit_sha),'') IS NULL
     OR coalesce(_contract_sha256,'') !~ '^[0-9a-f]{64}$'
     OR nullif(btrim(_promoted_by),'') IS NULL
     OR jsonb_typeof(_validation_evidence) <> 'object'
     OR coalesce((_validation_evidence->>'contractValidated')::boolean,false) IS NOT TRUE
     OR coalesce((_validation_evidence->>'freezeValidated')::boolean,false) IS NOT TRUE
     OR coalesce((_validation_evidence->>'executorValidated')::boolean,false) IS NOT TRUE
     OR coalesce((_validation_evidence->>'recoveryValidated')::boolean,false) IS NOT TRUE
     OR coalesce((_validation_evidence->>'ledgerValidated')::boolean,false) IS NOT TRUE THEN
    RAISE EXCEPTION 'Evidência de promoção do Control-plane incompleta' USING ERRCODE='22023';
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended('unitos:master:control-plane-promotion',0));
  PERFORM pg_advisory_xact_lock(hashtextextended('unitos:master:installation-operations-freeze',0));
  SELECT * INTO STRICT _state FROM public.control_plane_release_state
    WHERE singleton IS TRUE FOR UPDATE;

  IF _state.generation <> _expected_generation
     OR _state.current_version IS DISTINCT FROM _expected_current_version
     OR _state.pinned_release IS DISTINCT FROM _expected_pinned_release
     OR _state.pinned_commit_sha IS DISTINCT FROM _expected_pinned_commit_sha THEN
    RAISE EXCEPTION 'Estado do Control-plane divergiu; promoção abortada' USING ERRCODE='40001';
  END IF;
  IF (SELECT count(*) FROM public.installation_operations_freeze WHERE singleton IS TRUE AND frozen IS TRUE) <> 1 THEN
    RAISE EXCEPTION 'Freeze global deve permanecer ativo durante a promoção' USING ERRCODE='55000';
  END IF;
  IF to_regprocedure('public.finalize_installation_operation(uuid,text,bigint,text,text,text,jsonb,jsonb,text,text,jsonb,text,boolean,boolean)') IS NULL
     OR to_regclass('public.installation_migration_reconciliation_evidence') IS NULL
     OR NOT EXISTS (SELECT 1 FROM supabase_migrations.schema_migrations WHERE version='20260919143000') THEN
    RAISE EXCEPTION 'Contrato, executor ou recovery do Control-plane não validados' USING ERRCODE='55000';
  END IF;

  _next_generation := _state.generation + 1;
  INSERT INTO public.control_plane_release_events(
    generation,previous_current_version,previous_pinned_release,previous_pinned_commit_sha,
    target_version,target_commit_sha,contract_sha256,validation_evidence,promoted_by
  ) VALUES (
    _next_generation,_state.current_version,_state.pinned_release,_state.pinned_commit_sha,
    btrim(_target_version),btrim(_target_commit_sha),lower(_contract_sha256),_validation_evidence,btrim(_promoted_by)
  );
  UPDATE public.control_plane_release_state SET
    current_version=btrim(_target_version), pinned_release=btrim(_target_version),
    pinned_commit_sha=btrim(_target_commit_sha), contract_sha256=lower(_contract_sha256),
    generation=_next_generation, promoted_by=btrim(_promoted_by), promoted_at=now(), updated_at=now()
  WHERE singleton IS TRUE AND generation=_expected_generation;
  IF NOT FOUND THEN RAISE EXCEPTION 'Fencing da promoção do Control-plane perdido' USING ERRCODE='40001'; END IF;
  RETURN jsonb_build_object('currentVersion',btrim(_target_version),'pinnedRelease',btrim(_target_version),
    'pinnedCommitSha',btrim(_target_commit_sha),'contractSha256',lower(_contract_sha256),'generation',_next_generation);
EXCEPTION WHEN NO_DATA_FOUND OR TOO_MANY_ROWS THEN
  RAISE EXCEPTION 'Estado do Control-plane ausente ou inválido' USING ERRCODE='55000';
END $$;
REVOKE ALL ON FUNCTION public.promote_control_plane_release(bigint,text,text,text,text,text,text,jsonb,text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.promote_control_plane_release(bigint,text,text,text,text,text,text,jsonb,text) TO service_role;

-- MASTER CLEAN INSTALLATION REPLACEMENT
-- MASTER 1.4.24: vínculo fail-closed para substituição limpa de instalações.
-- Control-plane only. Nunca incluir no pacote Client.

ALTER TABLE public.installations
  ADD COLUMN IF NOT EXISTS clean_replacement_of uuid REFERENCES public.installations(id) ON DELETE RESTRICT,
  ADD COLUMN IF NOT EXISTS pending_domain text;

CREATE UNIQUE INDEX IF NOT EXISTS installations_one_clean_replacement
  ON public.installations (clean_replacement_of)
  WHERE clean_replacement_of IS NOT NULL;

COMMENT ON COLUMN public.installations.clean_replacement_of IS
  'Instalação antiga preservada enquanto esta substituição limpa é provisionada e validada.';
COMMENT ON COLUMN public.installations.pending_domain IS
  'Domínio institucional preservado para cutover posterior; não é usado durante o provisionamento isolado.';

CREATE OR REPLACE FUNCTION public.prepare_clean_installation_replacement_cutover(
  _replacement_id uuid,
  _expected_release text
) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE
  _replacement public.installations%ROWTYPE;
  _source public.installations%ROWTYPE;
BEGIN
  SELECT * INTO _replacement FROM public.installations WHERE id=_replacement_id FOR UPDATE;
  IF NOT FOUND OR _replacement.clean_replacement_of IS NULL THEN
    RAISE EXCEPTION 'Substituição limpa não encontrada' USING ERRCODE='22023';
  END IF;
  SELECT * INTO STRICT _source FROM public.installations WHERE id=_replacement.clean_replacement_of FOR UPDATE;
  IF _replacement.active_operation_id IS NOT NULL OR _source.active_operation_id IS NOT NULL
     OR _replacement.status <> 'up_to_date' OR _replacement.health <> 'healthy'
     OR _replacement.current_version IS DISTINCT FROM _expected_release
     OR nullif(btrim(_replacement.pending_domain),'') IS NULL
     OR _replacement.domain IS NOT NULL THEN
    RAISE EXCEPTION 'Substituição ainda não possui evidência completa para o cutover' USING ERRCODE='55000';
  END IF;
  IF _source.domain IS DISTINCT FROM _replacement.pending_domain THEN
    RAISE EXCEPTION 'Domínio institucional divergiu desde a abertura da substituição' USING ERRCODE='55000';
  END IF;
  UPDATE public.installations SET clean_replacement_of=NULL,updated_at=now() WHERE id=_replacement.id;
  DELETE FROM public.installations WHERE id=_source.id;
  UPDATE public.installations SET name=_source.name,slug=_source.slug,domain=_replacement.pending_domain,
    pending_domain=NULL,notes=_source.notes,updated_at=now() WHERE id=_replacement.id;
  RETURN jsonb_build_object('replacementId',_replacement.id,'sourceId',_source.id,'domain',_replacement.pending_domain);
END $$;

REVOKE ALL ON FUNCTION public.prepare_clean_installation_replacement_cutover(uuid,text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.prepare_clean_installation_replacement_cutover(uuid,text) TO service_role;

